#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
patch_variant_truth.py — Kit 29j [variant-truth]
محرّك الفاريانت الحقيقي لصفحة المنتج: صورة كل لون + مقاساته الحقيقية + ثمنه + vid دقيق.
يعمل على الحالتين: مع/بدون كيت 29h (الاختيار آلي ببصمة GlassIcon).
Fail-closed: أي شي ما متوقع → ما يكتب والو → diag فـ kit29j-diag/
"""
import base64, json, os, sys, time

PAY = json.loads(base64.b64decode("").decode("utf-8"))
REL, MARKER = PAY["rel"], PAY["marker"]

def diag(reason, detail=""):
    d = "kit29j-diag"
    try:
        os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, f"diag-{int(time.time())}.txt"), "w", encoding="utf-8") as f:
            f.write(f"reason: {reason}\ndetail:\n{detail}\n")
    except Exception:
        pass
    print(f"❌ {reason}")
    if detail:
        print(f"   التفاصيل فـ {d}/")

def main():
    # ── 1) لقي الملف ──
    cands = [REL, REL.replace("app/", "src/app/")]
    path = next((c for c in cands if os.path.isfile(c)), None)
    if not path:
        diag("target-missing", "ما لقيتش " + REL)
        return 1

    with open(path, "rb") as f:
        raw = f.read()
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        diag("not-utf8", path)
        return 1

    # ── 2) idempotent ──
    if MARKER in text:
        print("✅ [variant-truth] مركّب قبل — والو ما نديروه (idempotent)")
        return 0

    # ── 3) حراس الحالة ──
    if "ProductDetailsClient" not in text or "use client" not in text:
        diag("unexpected-file-shape", f"{path} ما يشبهش ProductDetailsClient")
        return 1
    if "[variant-truth]" in text:
        diag("payload-sentinel-found", "بلاصة خاطئة؟")
        return 1

    has_29h = PAY["fingerprint_29h"] in text
    pairs = PAY["pairs_b"] if has_29h else PAY["pairs_a"]
    mode = "مع 29h (GlassIcon موجود)" if has_29h else "بلا 29h (GlassIcon ناقص)"
    print(f"🔎 الحالة: {mode} · {len(pairs)} زوج جراحي")

    # ── 4) تطبيق فالذاكرة — fail-closed على أول زوج ما يلقاش مرة وحدة بالضبط ──
    new_text = text
    for idx, (old, new, want) in enumerate(pairs):
        n = new_text.count(old)
        if n != want:
            detail = f"pair #{idx}: count={n} want={want}\n--- old (أول 400) ---\n{old[:400]}"
            diag("pair-mismatch", detail)
            print("   إلا الملف متبدد (29h ما مركبش؟) ركّب 29h الأول ولا اطلب نسخة متوافقة.")
            return 1
        new_text = new_text.replace(old, new, 1)

    # ── 5) حراس ما بعد ──
    missing = [m for m in PAY["must_have"] if m not in new_text]
    if missing:
        diag("post-must-have-missing", "\n".join(missing))
        return 1
    rem = [r for r in PAY["remnants"] if r in new_text]
    if rem:
        diag("old-remnants-found", "\n".join(rem))
        return 1
    if "</main>" not in new_text or "export default" not in new_text:
        diag("structure-broken", "</main> ولا export default ضايع")
        return 1

    # ── 6) backup + كتابة ذرّية ──
    bak = path + ".bak-kit29j"
    if not os.path.exists(bak):          # الأقدم ما يتمسش — أول backup هو الأصلي
        with open(bak, "wb") as f:
            f.write(raw)
        print(f"💾 backup: {bak}")
    tmp = path + ".tmp-kit29j"
    with open(tmp, "wb") as f:
        f.write(new_text.encode("utf-8"))
    os.replace(tmp, path)

    print("✅ [variant-truth] تركّب: محرّك الفاريانت الحقيقي خدام")
    print("   → python verify_variant_truth.py ثم npm run build")
    return 0

if __name__ == "__main__":
    sys.exit(main())
